110	import org.mockito.Mockito;
111	import org.springframework.beans.factory.annotation.Autowired;
112	import org.springframework.context.ApplicationContext;
113	import org.springframework.context.ApplicationEvent;
114	import org.springframework.context.ApplicationEventPublisher;
115	import org.springframework.context.PayloadApplicationEvent;
116	import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
117	import org.springframework.context.event.EventListener;
118	import org.springframework.core.type.filter.AnnotationTypeFilter;
119	import org.springframework.stereotype.Component;
120	import org.springframework.transaction.event.TransactionalEventListener;
121	
122	import java.lang.reflect.Constructor;
123	import java.lang.reflect.Field;
124	import java.lang.reflect.InvocationTargetException;
125	import java.lang.reflect.Method;
126	import java.lang.reflect.Modifier;
127	import java.util.ArrayList;
128	import java.util.Comparator;
129	import java.util.HashMap;
130	import java.util.HashSet;
131	import java.util.List;
132	import java.util.Map;
133	import java.util.Set;
134	
135	/**
136	 * 테스트용 객체 조립기.
137	 *
138	 * - 리포지토리·EntityManager 등 테스트 컨텍스트(@DataJpaTest)에 있는 빈은 그대로 쓴다.
139	 * - com.fream.back.domain 아래의 @Service/@Component 클래스는 실제 객체로 생성자 주입해 만든다.
140	 * - 그 밖의 의존(외부 연동·Redis·WebSocket 등)은 Mockito mock으로 채운다.
141	 * - ApplicationEventPublisher로 발행한 이벤트는 domain 아래 @EventListener/@TransactionalEventListener 메서드로 즉시 전달한다.
142	 */
143	final class Wiring {
144	
145	    private static final String DOMAIN = "com.fream.back.domain";
146	
147	    private final ApplicationContext ctx;
148	    private final Map<Class<?>, Object> instances = new HashMap<>();
149	    private final Set<Class<?>> building = new HashSet<>();
150	    private List<Class<?>> listenerClasses;
151	
152	    Wiring(ApplicationContext ctx) {
153	        this.ctx = ctx;
154	        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
155	    }
156	
157	    <T> Wiring with(Class<T> type, T instance) {
158	        instances.put(type, instance);
159	        return this;
160	    }
161	
162	    @SuppressWarnings("unchecked")
163	    <T> T get(Class<T> type) {
164	        Object existing = instances.get(type);
165	        if (existing != null) {
166	            return (T) existing;
167	        }
168	        if (type == String.class) {
169	            return (T) "";
170	        }
171	        if (type.isPrimitive()) {
172	            return (T) defaultPrimitive(type);
173	        }
174	        Object bean = ctx.getBeanProvider(type).getIfUnique();
175	        if (bean != null) {
176	            return (T) bean;
177	        }
178	        Object created;
179	        if (isDomainComponent(type) && !building.contains(type)) {
180	            building.add(type);
181	            try {
182	                created = construct(type);
183	            } finally {
184	                building.remove(type);
185	            }
186	        } else {
187	            created = Mockito.mock(type);
188	        }
189	        instances.put(type, created);
190	        return (T) created;
191	    }
192	
193	    private static boolean isDomainComponent(Class<?> t) {
194	        return t.getName().startsWith(DOMAIN + ".")
195	                && !t.isInterface()
196	                && !Modifier.isAbstract(t.getModifiers())
197	                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
198	    }
199	
200	    private Object construct(Class<?> type) {
201	        try {
202	            Constructor<?> ctor = null;
203	            for (Constructor<?> c : type.getDeclaredConstructors()) {
204	                if (c.isAnnotationPresent(Autowired.class)) {
205	                    ctor = c;
206	                }
207	            }
208	            if (ctor == null) {
209	                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
210	                        .max(Comparator.comparingInt(Constructor::getParameterCount))
211	                        .orElseThrow();
212	            }
213	            Class<?>[] params = ctor.getParameterTypes();
214	            Object[] args = new Object[params.length];
215	            for (int i = 0; i < params.length; i++) {
216	                args[i] = get(params[i]);
217	            }
218	            ctor.setAccessible(true);
219	            Object obj = ctor.newInstance(args);
220	            instances.put(type, obj);
221	            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
222	                for (Field f : c.getDeclaredFields()) {
223	                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
224	                        f.setAccessible(true);
225	                        if (f.get(obj) == null) {
226	                            f.set(obj, get(f.getType()));
227	                        }
228	                    }
229	                }
230	            }
231	            return obj;
232	        } catch (ReflectiveOperationException e) {
233	            throw new IllegalStateException("cannot build " + type.getName(), e);
234	        }
235	    }
236	
237	    private void dispatch(Object event) {
238	        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
239	        for (Class<?> listenerType : listenerClasses()) {
240	            for (Method m : listenerType.getDeclaredMethods()) {
241	                boolean listener = m.isAnnotationPresent(EventListener.class)
242	                        || m.isAnnotationPresent(TransactionalEventListener.class);
243	                if (!listener || m.getParameterCount() != 1) {
244	                    continue;
245	                }
246	                Class<?> p = m.getParameterTypes()[0];
247	                Object arg = p.isInstance(payload) ? payload
248	                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
249	                if (arg == null) {
250	                    continue;
251	                }
252	                try {
253	                    m.setAccessible(true);
254	                    m.invoke(get(listenerType), arg);
255	                } catch (InvocationTargetException e) {
256	                    Throwable t = e.getTargetException();
257	                    if (t instanceof RuntimeException re) {
258	                        throw re;
259	                    }
260	                    throw new IllegalStateException(t);
261	                } catch (IllegalAccessException e) {
262	                    throw new IllegalStateException(e);
263	                }
264	            }
265	        }
266	    }
267	
268	    private List<Class<?>> listenerClasses() {
269	        if (listenerClasses == null) {
270	            listenerClasses = new ArrayList<>();
271	            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
272	            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
273	            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
274	                try {
275	                    Class<?> c = Class.forName(bd.getBeanClassName());
276	                    for (Method m : c.getDeclaredMethods()) {
277	                        if (m.isAnnotationPresent(EventListener.class)
278	                                || m.isAnnotationPresent(TransactionalEventListener.class)) {
279	                            listenerClasses.add(c);
280	                            break;
281	                        }
282	                    }
283	                } catch (ClassNotFoundException | LinkageError ignored) {
284	                    // 로드할 수 없는 후보는 건너뛴다
285	                }
286	            });
287	        }
288	        return listenerClasses;
289	    }
290	
291	    private static Object defaultPrimitive(Class<?> t) {
292	        if (t == boolean.class) return false;
293	        if (t == char.class) return '\0';
294	        if (t == byte.class) return (byte) 0;
295	        if (t == short.class) return (short) 0;
296	        if (t == int.class) return 0;
297	        if (t == long.class) return 0L;
298	        if (t == float.class) return 0f;
299	        return 0d;
300	    }
301	}
