347	    /**
348	     * 주문에 대한 배송 정보를 생성합니다.
349	     *
350	     * @param order 주문 엔티티
351	     * @param receiverName 수령인 이름
352	     * @param receiverPhone 수령인 전화번호
353	     * @param postalCode 우편번호
354	     * @param address 배송지 주소
355	     * @return 생성된 배송 정보
356	     */
357	    @Transactional
358	    public OrderShipment createOrderShipment(Order order, String receiverName, String receiverPhone,
359	                                             String postalCode, String address) {
360	        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
361	                order.getId(), receiverName);
362	
363	        OrderShipment shipment = OrderShipment.builder()
364	                .order(order)
365	                .receiverName(receiverName)
366	                .receiverPhone(receiverPhone)
367	                .postalCode(postalCode)
368	                .address(address)
369	                .status(ShipmentStatus.PENDING) // 초기 상태 설정
370	                .build();
371	
372	        OrderShipment savedShipment = orderShipmentRepository.save(shipment);
373	        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
374	                savedShipment.getId(), order.getId());
375	
376	        return savedShipment;
377	    }
