408	    /**
409	     * 주문 완료에 따라 판매 상태를 'SOLD'로 변경합니다.
410	     *
411	     * @param orderId 주문 ID
412	     */
413	    @Transactional
414	    public void updateSaleStatusToSold(Long orderId) {
415	        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);
416	
417	        // SaleBid 조회
418	        SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
419	        if (saleBid != null) {
420	            Sale sale = saleBid.getSale();
421	            if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
422	                log.info("Sale 상태 'SOLD'로 변경: saleId={}, sellerId={}",
423	                        sale.getId(), sale.getSeller().getId());
424	
425	                sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
426	
427	                // 창고 상태 업데이트
428	                if (sale.isWarehouseStorage()) {
429	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
430	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
431	                }
432	
433	                // 판매자에게 알림 생성
434	                User seller = sale.getSeller();
435	                notificationCommandService.createNotification(
436	                        seller.getId(),
437	                        NotificationCategory.SHOPPING,
438	                        NotificationType.BID,
439	                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
440	                );
441	
442	                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
443	                        seller.getId(), sale.getId());
444	            } else {
445	                log.debug("Sale 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
446	            }
447	        } else {
448	            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
449	        }
450	
451	        // OrderBid 조회
452	        try {
453	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
454	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
455	
456	            if (orderBid != null) {
457	                Sale sale = orderBid.getSale();
458	                if (sale != null && sale.getStatus().canTransitionTo(SaleStatus.SOLD)) {
459	                    log.info("OrderBid 기반 Sale 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
460	                            orderBid.getId(), sale.getId());
461	
462	                    sale.updateStatus(SaleStatus.SOLD); // 더티 체크에 의해 자동으로 업데이트됨
463	
464	                    // 판매자에게 알림 생성
465	                    User seller = sale.getSeller();
466	                    notificationCommandService.createNotification(
467	                            seller.getId(),
468	                            NotificationCategory.SHOPPING,
469	                            NotificationType.BID,
470	                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
471	                    );
472	
473	                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
474	                            seller.getId(), sale.getId());
475	                } else {
476	                    log.debug("Sale 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
477	                }
478	            }
479	        } catch (IllegalArgumentException e) {
480	            log.warn("OrderBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());
481	            // OrderBid가 없는 경우 예외로 중단하지 않고 진행
482	        }
483	
484	        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
485	    }
