492	    @Transactional
493	    public void completeOrder(Long orderId) {
494	        log.info("주문 완료 처리 시작: orderId={}", orderId);
495	
496	        try {
497	            // OrderBid 조회
498	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
499	                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));
500	
501	            Order order = orderBid.getOrder();
502	            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
503	                    order.getId(), order.getUser().getId(), order.getStatus());
504	
505	            // 주문 상태를 COMPLETED로 변경
506	            order.updateStatus(OrderStatus.COMPLETED);
507	            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);
508	
509	            // 판매 상태 변경 로직
510	            updateSaleStatusToSold(orderId);
511	
512	            // 주문 완료 알림
513	            User buyer = order.getUser();
514	            notificationCommandService.createNotification(
515	                    buyer.getId(),
516	                    NotificationCategory.SHOPPING,
517	                    NotificationType.BID,
518	                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
519	            );
520	
521	            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());
522	
523	        } catch (Exception e) {
524	            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
525	            throw new ShipmentException(
526	                    ShipmentErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
527	                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
528	                    e
529	            );
530	        }
531	    }
