533	    /**
534	     * 배송 정보에 운송장 정보를 업데이트하고 관련 상태를 변경합니다.
535	     *
536	     * @param shipmentId 배송 ID
537	     * @param courier 택배사 이름
538	     * @param trackingNumber 운송장 번호
539	     */
540	    @Transactional
541	    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
542	        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
543	                shipmentId, courier, trackingNumber);
544	
545	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
546	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
547	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
548	        }
549	
550	        try {
551	            OrderShipment shipment = orderShipmentRepository.findById(shipmentId)
552	                    .orElseThrow(() -> new ShipmentException(
553	                            ShipmentErrorCode.SHIPMENT_NOT_FOUND,
554	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
555	                    ));
556	
557	            // 운송장 정보 업데이트
558	            shipment.updateTrackingInfo(courier, trackingNumber);
559	
560	            // 배송 상태가 변경되었으므로 주문 상태도 업데이트
561	            Order order = shipment.getOrder();
562	            order.updateStatus(OrderStatus.IN_TRANSIT);
563	
564	            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());
565	
566	            // 주문한 사용자에게 알림 생성
567	            User buyer = order.getUser();
568	            notificationCommandService.createNotification(
569	                    buyer.getId(),
570	                    NotificationCategory.SHOPPING,
571	                    NotificationType.BID,
572	                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
573	            );
574	
575	            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());
576	
577	            // 판매 상태 업데이트 및 알림 전송
578	            updateSaleStatusToSold(order.getId());
579	
580	            // SaleBid에서 Sale 조회 및 창고 상태 업데이트
581	            SaleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
582	            if (saleBid != null) {
583	                Sale sale = saleBid.getSale();
584	                if (sale != null && sale.isWarehouseStorage()) {
585	                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
586	                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
587	                }
588	            }
589	
590	            // OrderBid 상태를 COMPLETED로 변경
591	            updateOrderAndSaleBidStatusToCompleted(order.getId());
592	
593	            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
594	
595	        } catch (ShipmentException e) {
596	            throw e;
597	        } catch (Exception e) {
598	            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
599	            throw new ShipmentException(
600	                    ShipmentErrorCode.SHIPMENT_NOT_FOUND,
601	                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
602	                    e
603	            );
604	        }
605	    }
