607	    /**
608	     * 전체 배송 상태를 주기적으로 업데이트합니다.
609	     */
610	    @Transactional
611	    public void updateShipmentStatuses() {
612	        log.info("전체 배송 상태 업데이트 시작");
613	
614	        // 1. IN_TRANSIT 또는 OUT_FOR_DELIVERY 상태의 OrderShipment 조회
615	        List<OrderShipment> shipments = orderShipmentRepository.findByStatusIn(
616	                List.of(ShipmentStatus.IN_TRANSIT, ShipmentStatus.OUT_FOR_DELIVERY)
617	        );
618	
619	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
620	
621	        int successCount = 0;
622	        int errorCount = 0;
623	
624	        for (OrderShipment shipment : shipments) {
625	            try {
626	                String trackingNumber = shipment.getTrackingNumber();
627	                if (trackingNumber == null || trackingNumber.isBlank()) {
628	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
629	                    errorCount++;
630	                    continue;
631	                }
632	
633	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
634	                        shipment.getId(), trackingNumber);
635	
636	                // 2. CJ대한통운에서 현재 배송 상태 추출
637	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
638	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
639	
640	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
641	                        shipment.getId(), currentStatus, newStatus);
642	
643	                // 현재 상태와 동일한 경우 중복 처리 방지
644	                if (shipment.getStatus() == newStatus) {
645	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
646	                            shipment.getId(), newStatus);
647	                    successCount++;
648	                    continue;
649	                }
650	
651	                // 3. 배송 상태가 DELIVERED인 경우 Order와 Shipment 상태 업데이트
652	                if (newStatus == ShipmentStatus.DELIVERED) {
653	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
654	
655	                    shipment.updateStatus(newStatus);
656	                    Order order = shipment.getOrder();
657	                    order.updateStatus(OrderStatus.COMPLETED);
658	
659	                    // 배송 완료 알림 전송
660	                    User buyer = order.getUser();
661	                    notificationCommandService.createNotification(
662	                            buyer.getId(),
663	                            NotificationCategory.SHOPPING,
664	                            NotificationType.BID,
665	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
666	                    );
667	
668	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
669	                            buyer.getId(), order.getId());
670	
671	                } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY &&
672	                        shipment.getStatus() != ShipmentStatus.OUT_FOR_DELIVERY) {
673	                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
674	                    shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
675	
676	                } else {
677	                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
678	                            shipment.getId(), newStatus);
679	                    shipment.updateStatus(newStatus);
680	                }
681	
682	                orderShipmentRepository.save(shipment);
683	                successCount++;
684	
685	            } catch (Exception e) {
686	                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
687	                        shipment.getId(), e.getMessage(), e);
688	                errorCount++;
689	            }
690	        }
691	
692	        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
693	    }
