695	    /**
696	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
697	     *
698	     * @param statusText 배송사 상태 텍스트
699	     * @return 매핑된 ShipmentStatus
700	     */
701	    private ShipmentStatus mapToShipmentStatus(String statusText) {
702	        return switch (statusText) {
703	            case "배송완료" -> ShipmentStatus.DELIVERED;
704	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
705	            default -> ShipmentStatus.IN_TRANSIT;
706	        };
707	    }
