709	    /**
710	     * OrderBid와 SaleBid의 상태를 COMPLETED로 업데이트합니다.
711	     *
712	     * @param orderId 주문 ID
713	     */
714	    @Transactional
715	    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
716	        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);
717	
718	        try {
719	            // OrderBid 조회
720	            OrderBid orderBid = orderBidQueryService.findByOrderId(orderId)
721	                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));
722	
723	            // 상태를 COMPLETED로 업데이트
724	            if (orderBid.getStatus() == com.fream.back.domain.order.entity.BidStatus.MATCHED) {
725	                log.debug("OrderBid 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
726	                orderBid.updateStatus(com.fream.back.domain.order.entity.BidStatus.COMPLETED);
727	            }
728	
729	            // SaleBid 상태 업데이트
730	            SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
731	            if (saleBid != null && saleBid.getStatus() == BidStatus.MATCHED) {
732	                log.debug("SaleBid 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
733	                saleBid.updateStatus(BidStatus.COMPLETED);
734	            }
735	
736	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
737	
738	        } catch (Exception e) {
739	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
740	            // 상태 변경 실패는 로그만 남기고 진행 (주요 로직에 영향 주지 않음)
741	        }
742	    }
