744	    /**
745	     * 단일 송장에 대해 즉시 상태를 갱신하고, 최종 상태를 반환합니다.
746	     *
747	     * @param shipmentId 배송 ID
748	     * @param courier 택배사
749	     * @param trackingNumber 운송장 번호
750	     * @return 갱신된 배송 상태
751	     * @throws ShipmentException 배송 상태 조회 실패 시 발생
752	     */
753	    @Transactional
754	    public ShipmentStatus updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
755	        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
756	                shipmentId, courier, trackingNumber);
757	
758	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
759	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
760	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
761	        }
762	
763	        try {
